create table RB_LIMIT_CTRL_CUSTOM_INFO (CHECK_OBJ_VAL VARCHAR(50) not null  ,LIMIT_CTRL_AMT DECIMAL(38,2) null  ,CREATE_TIMESTAMP VARCHAR(26) not null  ,EFFECT_DATE TIMESTAMP(3) null  ,LAST_UPD_TIMESTAMP VARCHAR(26) not null  ,LIMIT_SCENE_NO VARCHAR(50) not null  ,LIMIT_CTRL_NUM INT null  ,TEMP_LIMIT_FLAG VARCHAR(1) null  ,CTRL_ITEM_TYPE VARCHAR(1) null  ,CLIENT_NO VARCHAR(22) not null  ,EXPIRE_DATE TIMESTAMP(3) null  , primary key(CHECK_OBJ_VAL,LIMIT_SCENE_NO));